-- 模式2批5：历史表租户列补充。
-- 这些表来自不同业务模块，部分仅在功能启用或后续 baseline 中创建；不能用占位表掩盖缺失。
-- 表存在时补列和索引，表不存在时安全跳过，保持旧库和空库均可重放。
DO $$
DECLARE t TEXT; idx TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'ab_test_results','acceptance_checklists','action_plans','agent_admin_alert_log','agent_appeals','agent_autonomous_logs','agent_autonomous_tasks','agent_collaboration_archives','agent_collaboration_logs','agent_configs','agent_eval_runs','agent_experience','agent_issues','agent_issues_reports','agent_long_memory','agent_memory','agent_messages','agent_metric_cache','agent_notifications','agent_optimization_history','agent_prompt_templates','agent_quality_audits','agent_reply_templates','agent_rules','agent_scores','agent_sessions','agent_task_logs','agent_v2_configs','agent_v2_cron_runs','agent_v2_data_alert_dedupe','agent_v2_morning_briefing_sends','agent_v2_pllm_monthly_report_log','agent_v2_scheduled_report_sends','agent_visual_audits','analysis_rules','analysis_sop','anomaly_pending_notifications','anomaly_triggers','attention_scores','auto_ops_runs','automated_test_results','bad_reviews','bitable_submissions_archive','brand_voice_samples','business_entity_relations','checkin_records','cn_holiday_calendar','config_audit_log','content_performance','creative_assets','customer_identities','daily_reports','data_quality_logs','decision_log','diagnosis_feedback','dish_library_costs','dish_name_aliases','dish_station_mapping','employee_attachments','employee_scores','employee_training_records','employment_records','entity_health_snapshot','escalation_chains','exam_results','file_access_logs','files','generated_posters','growth_alerts','growth_campaign_jobs','growth_campaign_plans','growth_campaigns','growth_churn_predictions','growth_content_calendar','growth_coupons','growth_customer_profiles','growth_customers','growth_daily_metrics','growth_delivery_logs','growth_events','growth_execution_logs','growth_holdout_members','growth_learnings','growth_menu_health_reports','growth_profile_signals','growth_redemptions','growth_segment_members','growth_sms_suppression','growth_stored_value_members','growth_strategy_evaluations','growth_strategy_explanations','growth_sync_failures','growth_touch_rules','hr_rating_configs','hrms_reward_punishment_records','hrms_user_notifications','idempotency_keys','ingredient_categories','ingredient_library','kitchen_exec_logs','kitchen_reports','kitchen_sop_steps','kitchen_step_logs','knowledge_base','knowledge_edit_history','kpi_snapshots','kpi_targets','margin_targets','marketing_campaigns','marketing_case_library','marketing_payment_rules','marketing_templates','master_events','master_tasks','material_receiving_reports','metric_dictionary','monthly_margins','ops_tasks','performance_invalidation_records','platform_data_cache','point_records','poster_templates','public_channels','public_promo_tasks','recipe_component_ingredients','recipe_component_steps','recipe_components','recipes','recurring_reward_templates','regression_check_results','revenue_targets','rhythm_logs','sales_growth_snapshot','scheduler_heartbeat','schedules','sop_cases','sop_definitions','sop_distributions','sop_questions','sop_quiz_questions','sop_steps','sop_versions','store_duty_bindings','store_marketing_constraints','store_marketing_profiles','store_meeting_reports','store_ratings','stores','strategy_rules','strategy_variants','table_visit_records','task_assignments','task_evidences','task_experience_logs','task_locks','task_reviews','task_runs','temp_staffing_requests','training_plan_phases','training_plans','training_sessions','training_tasks','user_login_log','user_reads','user_sessions'
  ] LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS tenant_id VARCHAR(80) NOT NULL DEFAULT %L', t, 'default');
      idx := 'idx_' || t || '_tenant';
      EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I(tenant_id)', idx, t);
    END IF;
  END LOOP;
END $$;
